import 'dart:convert';import 'package:shared_preferences/shared_preferences.dart';import '../models/commitment.dart';import '../models/employee.dart';
class StorageService {static late SharedPreferences _p;static Future<void> init()async{_p=await SharedPreferences.getInstance();}static List<Commitment> commitments()=>((_p.getStringList('commitments')??[]).map((s)=>Commitment.fromJson(jsonDecode(s))).toList());static Future<void> saveCommitment(Commitment c)async{final x=commitments()..removeWhere((e)=>e.id==c.id)..add(c);await _p.setStringList('commitments',x.map((e)=>jsonEncode(e.toJson())).toList());}static List<Employee> employees()=>((_p.getStringList('employees')??[]).map((s)=>Employee.fromJson(jsonDecode(s))).toList());static Future<void> saveEmployee(Employee e)async{final x=employees()..removeWhere((a)=>a.id==e.id)..add(e);await _p.setStringList('employees',x.map((a)=>jsonEncode(a.toJson())).toList());}static Employee? findEmployee(String name){for(final e in employees()){if(e.name.contains(name)||name.contains(e.name))return e;}return null;}static String get apiKey=>_p.getString('gemini_api_key')??'';static Future<void> setApiKey(String v)=>_p.setString('gemini_api_key',v);}
